const settle = (page) => page.waitForTimeout(800)

const browser = await chromium.launch({ channel: "chrome", headless: true })
const adminToken = await apiToken(ADMIN)
const tempEmails = []

try {
  // ---------------------------------------------------------------- admin
  {
    const ctx = await browser.newContext()
