    check("admin: Add User visible", await page.getByRole("button", { name: "Add User" }).isVisible())
    await page.locator("table tbody tr").first().waitFor()
    const actionButtons = await page.locator("table tbody tr td:last-child button").count()
    check("admin: row action menus present", actionButtons > 0, `${actionButtons} buttons`)
    const badges = await page.locator("table tbody").getByText(/^(Admin|Manager|Member)$/).allTextContents()
    check("admin: role badges render", badges.includes("Admin") && badges.includes("Manager"), badges.join(","))

    // create a manager through the dialog
    const email = `ui-manager-${Date.now()}@example.com`
    tempEmails.push(email)
    await page.getByRole("button", { name: "Add User" }).click()
    const dialog = page.getByRole("dialog")
    check("admin: no 'Is superuser?' in Add User", (await dialog.getByText("Is superuser?").count()) === 0)
    await dialog.getByPlaceholder("Email").fill(email)
    await dialog.getByPlaceholder("Password").first().fill("ui-password-123")
    await dialog.getByPlaceholder("Password").nth(1).fill("ui-password-123")
    await dialog.getByLabel("Role").click()
    await page.getByRole("option", { name: "Manager" }).click()
    await dialog.getByRole("button", { name: "Save" }).click()
    await page.getByText("User created successfully").waitFor()
    const row = page.locator("table tbody tr", { hasText: email })
    check("admin: created user shows Manager badge", (await row.getByText("Manager", { exact: true }).count()) === 1)

    // edit dialog: role select reflects current role
    await row.locator("td:last-child button").click()
    await page.getByRole("menuitem", { name: "Edit User" }).click()
    const editDialog = page.getByRole("dialog")
    const roleText = (await editDialog.getByLabel("Role").textContent())?.trim()
    check("admin: Edit User role select shows Manager", roleText === "Manager", roleText)
    await editDialog.getByLabel("Role").click()
    await page.getByRole("option", { name: "Member" }).click()
    await editDialog.getByRole("button", { name: "Save" }).click()
    await page.getByText("User updated successfully").waitFor()
    await settle(page)
    check("admin: edited user now Member", (await row.getByText("Member", { exact: true }).count()) === 1)

    await page.goto(`${WEB}/settings`)
    await page.getByRole("tab", { name: "My profile" }).waitFor()
    check("admin: settings has no Danger zone", (await page.getByRole("tab", { name: "Danger zone" }).count()) === 0)

    await page.goto(`${WEB}/metrics`)
    await page.getByText("Total users").waitFor()
    const total = await page.getByText("Total users").locator("..").textContent()
    check("admin: metrics page shows counts", /\d/.test(total ?? ""), total?.trim())
    await ctx.close()
  }

  // -------------------------------------------------------------- manager
  {
    const ctx = await browser.newContext()
    const page = await ctx.newPage()
    await login(page, MANAGER)
    check("manager: sidebar shows Metrics + Admin", (await navHas(page, "Metrics")) && (await navHas(page, "Admin")))
    await page.goto(`${WEB}/admin`)
    await page.locator("table tbody tr").first().waitFor()
    check("manager: no Add User", (await page.getByRole("button", { name: "Add User" }).count()) === 0)
    check("manager: no row action menus", (await page.locator("table tbody tr td button").count()) === 0)
    check("manager: read-only subtitle", await page.getByText("View user accounts (read-only)").isVisible())
    await page.goto(`${WEB}/metrics`)
    await page.getByText("Total users").waitFor()
    check("manager: metrics page loads", true)
    await page.goto(`${WEB}/settings`)
    await page.getByRole("tab", { name: "My profile" }).waitFor()
    check("manager: settings has Danger zone", (await page.getByRole("tab", { name: "Danger zone" }).count()) === 1)
    await ctx.close()
  }

  // --------------------------------------------------------------- member
  {
    const ctx = await browser.newContext()
    const page = await ctx.newPage()
    await login(page, MEMBER)
    check("member: sidebar hides Metrics + Admin", !(await navHas(page, "Metrics")) && !(await navHas(page, "Admin")))
    await page.goto(`${WEB}/admin`)
    await page.waitForURL(`${WEB}/`)
    check("member: /admin redirects to /", true)
    await page.goto(`${WEB}/metrics`)
    await page.waitForURL(`${WEB}/`)
    check("member: /metrics redirects to /", true)
    check("member: still logged in", (await page.evaluate(() => localStorage.getItem("access_token"))) !== null)
    await page.goto(`${WEB}/settings`)
    await page.getByRole("tab", { name: "My profile" }).waitFor()
    check("member: settings has Danger zone", (await page.getByRole("tab", { name: "Danger zone" }).count()) === 1)
    await ctx.close()
  }

  // ------------------------------------- 403 refetch / 401 logout (live)
  {
    const email = `ui-live-${Date.now()}@example.com`
    tempEmails.push(email)
    const created = await api(adminToken, "POST", "/users/", {
      email, password: "ui-password-123", role: "admin", is_active: true,
    })
    const id = created.json.id
    const ctx = await browser.newContext()
    const page = await ctx.newPage()
    await login(page, { email, password: "ui-password-123" })
    await page.goto(`${WEB}/admin`)
    await page.getByRole("button", { name: "Add User" }).waitFor()

    // demoted to manager behind the UI's back, then the stale UI attempts a write
    await api(adminToken, "PATCH", `/users/${id}`, { role: "manager" })
    await page.getByRole("button", { name: "Add User" }).click()
    const dialog = page.getByRole("dialog")
    await dialog.getByPlaceholder("Email").fill(`ui-never-${Date.now()}@example.com`)
    await dialog.getByPlaceholder("Password").first().fill("ui-password-123")
    await dialog.getByPlaceholder("Password").nth(1).fill("ui-password-123")
    await dialog.getByRole("button", { name: "Save" }).click()
    await page.getByText("The user doesn't have enough privileges").waitFor()
    check("403: error toast shown", true)
    await page.keyboard.press("Escape")
    await page.getByRole("button", { name: "Add User" }).waitFor({ state: "detached", timeout: 5000 })
    check("403: not logged out, still on /admin", page.url() === `${WEB}/admin`
      && (await page.evaluate(() => localStorage.getItem("access_token"))) !== null, page.url())
    check("403: UI refreshed to read-only (Add User gone)", true)
    check("403: sidebar still shows Admin (manager has users:read)", await navHas(page, "Admin"))

    // demoted to member: next 403 (users list refetch) -> currentUser refetch -> leave /admin
    await api(adminToken, "PATCH", `/users/${id}`, { role: "member" })
    await page.evaluate(() => window.dispatchEvent(new Event("focus")))
    await page.reload()
    await page.waitForURL(`${WEB}/`, { timeout: 5000 })
    check("403 (member): reload of /admin redirects to /", true)
    check("403 (member): sidebar Admin/Metrics hidden", !(await navHas(page, "Admin")) && !(await navHas(page, "Metrics")))

    // deactivated: next request is 401 -> logged out
    await api(adminToken, "PATCH", `/users/${id}`, { is_active: false })
    await nav(page).getByRole("link", { name: "Items", exact: true }).click()
    await page.waitForURL(`${WEB}/login`, { timeout: 5000 })
    check("401: deactivated user is sent to /login", true)
    check("401: token cleared", (await page.evaluate(() => localStorage.getItem("access_token"))) === null)
    await ctx.close()
  }
} catch (error) {
  check("script error", false, String(error).split("\n")[0])
} finally {
  // clean up temp users
  const list = await api(adminToken, "GET", "/users/?limit=1000")
  for (const u of list.json?.data ?? []) {
    if (tempEmails.includes(u.email) || u.email.startsWith("ui-never-")) {
      await api(adminToken, "DELETE", `/users/${u.id}`)
    }
  }
  await browser.close()
  const failed = results.filter((r) => !r.ok).length
  console.log(`\n${results.length - failed}/${results.length} passed`)
  process.exit(failed ? 1 : 0)
}

